import {CloudEvent} from './interface';
import axios from 'axios'
const request = require('supertest');

/**
 * CloudEvents class
 * @see https://godoc.org/github.com/cloudevents/sdk-go
 */
export const CloudEvents = class CloudEvents {
  // Only support CE major spec versions
  public static VersionV1 = 'VersionV1';
  public static HTTPBinaryV1 = 'HTTPBinaryV1';
  public static HTTPStructuredV1 = 'HTTPStructuredV1';
  public static HTTPBatchedV1 = 'HTTPBatchedV1';
  
  public static Binary = 'Binary';
  public static Structured = 'Structured';

  public static newEvent(event: CloudEvent): CloudEvent {
    return event;
  }

  public static newHTTPTransport(o: HTTPTransportOptions): CloudEventsTransport {
    return new CloudEventsTransport(o);
  }

  public static newClient(o: ClientOptions): CloudEventsClient {
    return new CloudEventsClient(o);
  }
}

class CloudEventsTransport {
  target: string;
  encoding: string; // binary

  constructor(options: HTTPTransportOptions) {
    this.target = options.target;
    this.encoding = options.encoding;
  }
}

class CloudEventsClient {
  options: ClientOptions;

  constructor(options: ClientOptions) {
    this.options = options;
  }

  public async send(e: CloudEvent) {
    if (!this.options.transport) {
      new Error('No client options set');
    }
    const transport = this.options.transport;
    // Debug console log
    console.log(`SEND: POST ${transport.target} ${JSON.stringify(e)}`);
    return await axios({
      url: transport.target,
      method: 'post',
      data: e,
    });
  }
}

interface HTTPTransportOptions {
  target: string
  encoding: string
}

interface ClientOptions {
  transport: CloudEventsTransport
}